// Street props generated by the world builder: vehicles, barricades, lamps, trees, debris.
// Geometry is merged per 128 m tile and streamed around the player.
import * as THREE from 'three';
import { F } from './collision.js';
import { CLASS } from './worldData.js';
import { seeded, hash2 } from '../core/util.js';
import { ZONES } from './locations.js';
import { merge } from './structure.js';

const TILE = 128;
const CAR_COLORS = [0xb8bcc0, 0x1c1e22, 0x22344e, 0x7a1e1e, 0xe8e6e0, 0x2e4a36, 0x5a5e66, 0x8a7a60, 0x3a2a2a, 0x9aa4ac];
export const VEH = {
  car: { L: 4.5, W: 1.8, H: 1.5, label: 'Bil', table: 'car', p: 0.35 },
  police: { L: 4.8, W: 1.85, H: 1.55, label: 'Polisbil', table: 'police', p: 1 },
  ambulance: { L: 5.8, W: 2.05, H: 2.6, label: 'Ambulans', table: 'ambulance', p: 1 },
  military: { L: 7.2, W: 2.7, H: 2.5, label: 'Militärfordon', table: 'military', p: 1 },
  bus: { L: 12, W: 2.55, H: 3.1, label: 'Buss', table: 'bus', p: 0.6 },
};

export class Props {
  constructor(game) {
    this.g = game; const W = game.world, P = W.props;
    this.tiles = new Map(); this.built = new Map();
    this.mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.25, map: game.tex.metal });
    this.matRough = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95 });
    this.treeMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, flatShading: true });
    const rng = seeded(31);
    const bucket = (x, z) => { const k = Math.floor((x + W.half) / TILE) * 1000 + Math.floor((z + W.half) / TILE); if (!this.tiles.has(k)) this.tiles.set(k, { cars: [], bars: [], lamps: [], trees: [], debris: [], cx: Math.floor((x + W.half) / TILE) * TILE - W.half + TILE / 2, cz: Math.floor((z + W.half) / TILE) * TILE - W.half + TILE / 2 }); return this.tiles.get(k); };
    const nearSafe = (x, z, m) => ZONES.some(zn => zn.type === 'safe' && Math.hypot(zn.x - x, zn.z - z) < zn.r + m);
    const blockedByBuilding = (x, z, r) => { let hit = false; game.collision.forNear(x, z, r, s => { if (s.owner && s.owner.verts) { const dx = s.bx - s.ax, dz = s.bz - s.az, L2 = dx * dx + dz * dz || 1; const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2)); if (Math.hypot(x - s.ax - dx * t, z - s.az - dz * t) < r) { hit = true; return false; } } }); return hit; };
    // vehicles
    let vi = 0;
    for (const [x, z, along, type0, burnt0] of P.cars) {
      const type = type0; const V = VEH[type];
      const yaw = along - Math.PI / 2; // builder stores the facade-normal angle; cars park parallel to the facade
      if (blockedByBuilding(x, z, V.W * 0.6) || game.isInsideHospital(x, z, 4)) continue;
      const y = W.terrainHeight(x, z);
      const burnt = !!burnt0;
      const car = { id: `car${vi++}`, x, z, y, yaw, type, burnt, color: CAR_COLORS[(rng() * CAR_COLORS.length) | 0], open: rng() < 0.3, tilt: rng() < 0.1 ? (rng() - 0.5) * 0.15 : 0 };
      bucket(x, z).cars.push(car);
      const segs = game.collision.addBox(x, z, yaw, V.W / 2, V.L / 2, y - 0.5, y + V.H, F.ALL, { metal: true, vehicle: car });
      if (!burnt && rng() < V.p) game.loot.container({ id: car.id, x, y: y + 1, z, label: V.label, table: V.table, r: Math.max(3.6, V.L * 0.62), hold: 1.8 });
      if (burnt && rng() < 0.08) game.fx.addEmitter(x, y + 0.9, z, 'fire', 0.9);
      if (type === 'police' && !burnt && rng() < 0.15) car.siren = true;
    }
    // barricades across streets (with a gap so districts stay connected)
    for (const [x0, z0, , , kind] of P.barricades) {
      if (nearSafe(x0, z0, 10) || game.isInsideHospital(x0, z0, 8)) continue;
      // find the shortest wall-to-wall chord through the point = across the street
      let best = null;
      for (let a = 0; a < Math.PI; a += Math.PI / 16) {
        const dx = Math.cos(a), dz = Math.sin(a), yy = W.terrainHeight(x0, z0) + 1;
        const h1 = game.collision.raycast(x0, yy, z0, dx, 0, dz, 30, F.PLAYER, true), h2 = game.collision.raycast(x0, yy, z0, -dx, 0, -dz, 30, F.PLAYER, true);
        if (!h1 || !h2) continue;
        const chord = h1.t + h2.t;
        if (!best || chord < best.chord) best = { chord, a, mid: (h1.t - h2.t) / 2 };
      }
      if (!best || best.chord < 5 || best.chord > 28) continue;
      const across = -best.a, x = x0 + Math.cos(best.a) * best.mid, z = z0 + Math.sin(best.a) * best.mid;
      const L = best.chord - 0.4;
      const gap = 2.4, gapPos = (rng() - 0.5) * (L - gap - 2);
      const b = { x, z, yaw: across, L, kind, gap, gapPos, y: W.terrainHeight(x, z) };
      bucket(x, z).bars.push(b);
      const c = Math.cos(across), s = Math.sin(across);
      const H = kind === 'military' ? 1.0 : kind === 'police' ? 0.85 : 1.6;
      const addPart = (t0, t1) => { if (t1 - t0 < 0.3) return; game.collision.addSegment(x + c * t0, z - s * t0, x + c * t1, z - s * t1, b.y - 0.5, b.y + H, F.PLAYER | F.ZOMBIE | (H > 1.2 ? F.BULLET | F.SIGHT : 0), { metal: kind !== 'military' }); };
      addPart(-L / 2, gapPos - gap / 2); addPart(gapPos + gap / 2, L / 2);
      if (kind === 'military' && rng() < 0.5) game.loot.container({ id: `bar${Math.round(x)}_${Math.round(z)}`, x: x + c * (gapPos + gap), y: b.y + 0.8, z: z - s * (gapPos + gap), label: 'Ammunitionslåda', table: 'military', r: 2.5 });
    }
    for (const [x, z, yaw] of P.lamps) { if (blockedByBuilding(x, z, 0.4)) continue; bucket(x, z).lamps.push({ x, z, yaw, y: W.terrainHeight(x, z), bent: rng() < 0.12 }); }
    let ti = 0;
    for (const [x, z, s, kind] of P.trees) {
      if (game.isInsideHospital(x, z, 3)) continue;
      const y = W.terrainHeight(x, z);
      bucket(x, z).trees.push({ x, z, s, kind, y, c: rng() });
      if (kind === 0 && ti++ % 1 === 0) game.collision.addBox(x, z, 0, 0.22 * s, 0.22 * s, y - 0.5, y + 4, F.ALL, 'tree');
    }
    let di = 0;
    for (const [x, z, yaw] of P.debris) {
      if (blockedByBuilding(x, z, 1.2) || nearSafe(x, z, 5)) continue;
      const kind = rng() < 0.4 ? 'rubble' : rng() < 0.6 ? 'trash' : 'crate';
      const y = W.terrainHeight(x, z);
      bucket(x, z).debris.push({ x, z, yaw, y, kind });
      if (kind !== 'rubble') game.loot.container({ id: `deb${di++}`, x, y: y + 0.5, z, label: kind === 'trash' ? 'Soppåsar' : 'Trälåda', table: kind === 'trash' ? 'trash' : 'crate', r: 2, hold: 1.2 });
      else game.collision.addBox(x, z, yaw, 1.3, 1.3, y - 0.5, y + 0.9, F.PLAYER | F.ZOMBIE, 'rubble');
    }
    // smoke plumes from burning buildings (visible from far away)
    let plumes = 0;
    for (const b of W.buildings) if (b.burnt && b.area > 600 && plumes < 14 && hash2(b.id, 5) < 0.25) { game.fx.addEmitter(b.cx, b.roof, b.cz, 'plume', 1); plumes++; }
  }

  update(px, pz) {
    const R = this.g.settings.quality === 'low' ? 230 : 320;
    let builds = 0;
    for (const [k, t] of this.tiles) {
      const d = Math.hypot(t.cx - px, t.cz - pz);
      const have = this.built.get(k);
      if (d < R && !have && builds < 1) { this.built.set(k, this.buildTile(t)); builds++; }
      else if (d > R + 90 && have) { for (const m of have) { this.g.scene.remove(m); m.geometry.dispose(); } this.built.delete(k); }
    }
  }

  buildTile(t) {
    const metal = [], rough = [], trees = [];
    for (const c of t.cars) vehicleGeo(c, metal, rough);
    for (const b of t.bars) barricadeGeo(b, metal, rough);
    for (const l of t.lamps) lampGeo(l, metal);
    for (const d of t.debris) debrisGeo(d, rough);
    for (const tr of t.trees) treeGeo(tr, trees);
    const out = [];
    const add = (geos, mat, shadow = true) => { if (!geos.length) return; const m = new THREE.Mesh(merge(geos), mat); m.castShadow = shadow; m.receiveShadow = true; this.g.scene.add(m); out.push(m); };
    add(metal, this.mat); add(rough, this.matRough); add(trees, this.treeMat);
    return out;
  }
}

// ---------------------------------------------------------------- geometry helpers
const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _e = new THREE.Euler(), _c = new THREE.Color();
export function part(list, geo, color, x, y, z, yaw, lx, ly, lz, rx = 0, rz = 0, roll = 0) {
  // place local offset (lx,ly,lz) rotated by yaw around (x,y,z)
  _e.set(rx, yaw, rz + roll, 'YXZ'); _q.setFromEuler(_e);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  _m.compose(new THREE.Vector3(x + lx * c + lz * s, y + ly, z - lx * s + lz * c), _q, new THREE.Vector3(1, 1, 1));
  geo.applyMatrix4(_m);
  _c.setHex(color);
  const n = geo.attributes.position.count, col = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { col[i * 3] = _c.r; col[i * 3 + 1] = _c.g; col[i * 3 + 2] = _c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  if (!geo.attributes.uv) geo.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));
  list.push(geo);
}
const box = (w, h, d) => new THREE.BoxGeometry(w, h, d);
const cyl = (r, h, n = 8) => new THREE.CylinderGeometry(r, r, h, n);

export function vehicleGeo(v, metal, rough) {
  const V = VEH[v.type]; const { x, z, yaw } = v; const y = v.y; const roll = v.tilt;
  const burnt = v.burnt;
  const body = burnt ? 0x2b2622 : v.type === 'police' ? 0xe9eef0 : v.type === 'ambulance' ? 0xd2e21a : v.type === 'military' ? 0x4b5320 : v.type === 'bus' ? 0x1b5ea8 : v.color;
  const glass = burnt ? 0x0c0c0c : 0x1d252c;
  const tire = 0x141414;
  const L = V.L, W = V.W;
  if (v.type === 'car' || v.type === 'police') {
    part(metal, box(W, 0.72, L), body, x, y, z, yaw, 0, 0.68, 0, 0, 0, roll);
    part(metal, box(W - 0.15, 0.6, L * 0.5), glass, x, y, z, yaw, 0, 1.33, -0.15, 0, 0, roll);
    part(metal, box(W - 0.2, 0.06, L * 0.46), body, x, y, z, yaw, 0, 1.64, -0.15, 0, 0, roll);
    if (v.type === 'police' && !burnt) {
      part(metal, box(W + 0.01, 0.25, L * 0.98), 0x1d4fa0, x, y, z, yaw, 0, 0.62, 0, 0, 0, roll);
      for (let i = -2; i <= 2; i++) part(metal, box(W + 0.02, 0.24, 0.45), 0xd8e000, x, y, z, yaw, 0, 0.62, i * 0.95, 0, 0, roll);
      part(metal, box(1.1, 0.12, 0.25), 0x2244ff, x, y, z, yaw, 0, 1.73, -0.1, 0, 0, roll);
    }
    if (!burnt) { part(metal, box(0.35, 0.12, 0.05), 0xdddddd, x, y, z, yaw, 0.6, 0.8, L / 2, 0, 0, roll); part(metal, box(0.35, 0.12, 0.05), 0xdddddd, x, y, z, yaw, -0.6, 0.8, L / 2, 0, 0, roll);
      part(metal, box(0.3, 0.1, 0.05), 0x8a0f0f, x, y, z, yaw, 0.65, 0.85, -L / 2, 0, 0, roll); part(metal, box(0.3, 0.1, 0.05), 0x8a0f0f, x, y, z, yaw, -0.65, 0.85, -L / 2, 0, 0, roll); }
    if (v.open && !burnt) part(metal, box(W - 0.1, 0.05, 0.9), body, x, y, z, yaw, 0, 1.45, -L / 2 + 0.2, -1.0, 0, roll); // open trunk lid
    for (const [wx, wz] of [[W / 2 - 0.1, L * 0.32], [-W / 2 + 0.1, L * 0.32], [W / 2 - 0.1, -L * 0.32], [-W / 2 + 0.1, -L * 0.32]]) {
      if (burnt && Math.random() < 0.4) continue;
      part(rough, cyl(0.33, 0.22, 10), tire, x, y, z, yaw, wx, 0.33, wz, 0, Math.PI / 2, roll);
    }
  } else if (v.type === 'ambulance') {
    part(metal, box(W, 1.9, L * 0.72), body, x, y, z, yaw, 0, 1.4, -L * 0.14, 0, 0, roll);
    part(metal, box(W, 1.1, L * 0.3), body, x, y, z, yaw, 0, 0.95, L * 0.34, 0, 0, roll);
    part(metal, box(W - 0.1, 0.55, 0.6), glass, x, y, z, yaw, 0, 1.75, L * 0.22, 0, 0, roll);
    if (!burnt) { part(metal, box(W + 0.02, 0.25, L * 0.72), 0x1e7a32, x, y, z, yaw, 0, 1.1, -L * 0.14, 0, 0, roll); part(metal, box(1.2, 0.15, 0.3), 0x2244ff, x, y, z, yaw, 0, 2.43, L * 0.2, 0, 0, roll); }
    for (const [wx, wz] of [[W / 2 - 0.1, L * 0.3], [-W / 2 + 0.1, L * 0.3], [W / 2 - 0.1, -L * 0.3], [-W / 2 + 0.1, -L * 0.3]]) part(rough, cyl(0.38, 0.25, 10), tire, x, y, z, yaw, wx, 0.38, wz, 0, Math.PI / 2, roll);
  } else if (v.type === 'military') {
    part(metal, box(W, 1.4, L), body, x, y, z, yaw, 0, 1.25, 0, 0, 0, roll);
    part(metal, box(W - 0.4, 0.5, L * 0.35), body, x, y, z, yaw, 0, 2.15, L * 0.28, 0.25, 0, roll);
    part(metal, box(1.2, 0.5, 1.2), body, x, y, z, yaw, 0, 2.2, -L * 0.1, 0, 0, roll);
    part(metal, cyl(0.06, 1.6), 0x2a2a2a, x, y, z, yaw, 0, 2.35, -L * 0.1 + 1.2, Math.PI / 2, 0, roll);
    for (let i = 0; i < 4; i++) for (const sd of [-1, 1]) part(rough, cyl(0.5, 0.35, 12), tire, x, y, z, yaw, sd * (W / 2 - 0.05), 0.5, -L * 0.36 + i * L * 0.24, 0, Math.PI / 2, roll);
  } else if (v.type === 'bus') {
    part(metal, box(W, 2.7, L), body, x, y, z, yaw, 0, 1.65, 0, 0, 0, roll);
    part(metal, box(W + 0.02, 0.9, L * 0.92), glass, x, y, z, yaw, 0, 2.2, -0.2, 0, 0, roll);
    if (!burnt) part(metal, box(W + 0.03, 0.18, L), 0xffffff, x, y, z, yaw, 0, 1.3, 0, 0, 0, roll);
    for (const wz of [L * 0.33, -L * 0.25, -L * 0.37]) for (const sd of [-1, 1]) part(rough, cyl(0.5, 0.3, 12), tire, x, y, z, yaw, sd * (W / 2 - 0.1), 0.5, wz, 0, Math.PI / 2, roll);
  }
}
function barricadeGeo(b, metal, rough) {
  const { x, z, y, yaw, L, kind, gap, gapPos } = b;
  const segs = [[-L / 2, gapPos - gap / 2], [gapPos + gap / 2, L / 2]];
  for (const [t0, t1] of segs) {
    if (t1 - t0 < 0.3) continue;
    if (kind === 'military') {
      for (let t = t0 + 0.3; t < t1; t += 0.62) for (let row = 0; row < 3; row++) {
        const yy = y + row * 0.33; const off = row % 2 ? 0.3 : 0;
        if (t + off > t1) continue;
        part(rough, box(0.6, 0.32, 0.42), 0x7a6e4e, x, yy, z, b.yaw + Math.PI / 2, 0, 0.16, t + off, 0, 0);
      }
    } else if (kind === 'police') {
      for (let t = t0 + 0.65; t < t1; t += 1.35) part(rough, box(0.6, 0.82, 1.25), 0xb8b4aa, x, y, z, b.yaw + Math.PI / 2, 0, 0.41, t, 0, 0);
      part(metal, box(0.03, 0.08, t1 - t0), 0xdd2222, x, y, z, b.yaw + Math.PI / 2, 0, 1.0, (t0 + t1) / 2, 0, 0);
    } else {
      for (let t = t0 + 0.6; t < t1; t += 1.1) {
        const h = 0.6 + hash2(t * 10, x) * 1.0;
        part(rough, box(1.0, h, 0.9 + hash2(t, z) * 0.6), [0x5a4a36, 0x3a3a3a, 0x6b5a3a, 0x444a50][(hash2(t, x) * 4) | 0], x, y, z, b.yaw + Math.PI / 2, 0, h / 2, t, 0, (hash2(t, 3) - 0.5) * 0.4);
      }
      part(metal, box(0.05, 1.6, t1 - t0), 0x555555, x, y, z, b.yaw + Math.PI / 2, 0.5, 0.8, (t0 + t1) / 2, 0, 0); // fence
    }
  }
}
function lampGeo(l, metal) {
  const tilt = l.bent ? 0.35 : 0;
  part(metal, cyl(0.08, 6, 6), 0x50555a, l.x, l.y, l.z, l.yaw, 0, 3, 0, 0, tilt);
  part(metal, box(0.12, 0.12, 1.4), 0x50555a, l.x, l.y, l.z, l.yaw, -Math.sin(tilt) * 6, 6 - (l.bent ? 0.3 : 0), 0.6, 0, 0);
  part(metal, box(0.35, 0.15, 0.5), 0x2a2c2e, l.x, l.y, l.z, l.yaw, -Math.sin(tilt) * 6, 5.9 - (l.bent ? 0.3 : 0), 1.25, 0, 0);
}
function debrisGeo(d, rough) {
  const { x, y, z, yaw, kind } = d;
  if (kind === 'rubble') {
    for (let i = 0; i < 7; i++) { const s = 0.3 + hash2(i, x) * 0.9; part(rough, box(s * 1.4, s * 0.7, s), [0x8a8278, 0x6e665e, 0x9a8a72, 0x5a5048][i % 4], x, y, z, yaw + i, (hash2(i, z) - 0.5) * 2.2, s * 0.3, (hash2(z, i) - 0.5) * 2.2, hash2(i, 9) * 0.6, hash2(i, 8) * 0.6); }
  } else if (kind === 'trash') {
    for (let i = 0; i < 4; i++) part(rough, new THREE.IcosahedronGeometry(0.35 + hash2(i, x) * 0.15, 0), 0x151515, x, y, z, yaw, (i % 2) * 0.6 - 0.3, 0.25, ((i / 2) | 0) * 0.6 - 0.3);
    part(rough, box(0.8, 1.1, 0.7), 0x2d5a2d, x, y, z, yaw, 0.9, 0.55, 0); // bin
  } else {
    part(rough, box(1.0, 0.8, 0.8), 0x7a5a36, x, y, z, yaw, 0, 0.4, 0);
    part(rough, box(0.8, 0.6, 0.6), 0x6a4e2e, x, y, z, yaw + 0.4, 0.4, 0.8 + 0.3, 0.1);
  }
}
function treeGeo(t, out) {
  const { x, y, z, s, kind } = t;
  const trunkC = 0x4a3a2a;
  if (kind === 2) { // pine / spruce
    const h = 9 * s;
    part(out, cyl(0.18 * s, h * 0.5, 5), trunkC, x, y, z, 0, 0, h * 0.25, 0);
    const greens = [0x1e3420, 0x24402a, 0x2a3a22];
    for (let i = 0; i < 3; i++) part(out, new THREE.ConeGeometry((2.4 - i * 0.6) * s, h * 0.38, 7), greens[i], x, y, z, t.c * 6, 0, h * (0.35 + i * 0.2), 0);
  } else {
    const h = (kind === 1 ? 8 : 6) * s;
    part(out, cyl(0.2 * s, h * 0.55, 5), trunkC, x, y, z, 0, 0, h * 0.27, 0);
    // late-autumn Göteborg: browns, yellows and some bare-ish crowns
    const cols = [0x5a5a26, 0x6e5a22, 0x4a5228, 0x7a4a1e, 0x3e4a26, 0x6a6a3a];
    const col = cols[(t.c * cols.length) | 0];
    part(out, new THREE.IcosahedronGeometry(2.3 * s, 0), col, x, y, z, t.c * 6, 0, h * 0.72, 0);
    part(out, new THREE.IcosahedronGeometry(1.6 * s, 0), col, x, y, z, t.c * 3, 0.9 * s, h * 0.9, 0.4 * s);
  }
}
